-- seed_sb_products.sql
-- Public storefront fields only (handle, title and name variants of active products), used by
-- ai-briefing to match discovery topics to the catalog. Internal tags and inactive products
-- are not included. Safe to re-run: ON CONFLICT (handle) updates these columns only and
-- leaves tags and is_active untouched.

ON CONFLICT (handle) DO UPDATE SET
  title           = EXCLUDED.title,
  common_name     = EXCLUDED.common_name,
  scientific_name = EXCLUDED.scientific_name,
  short_name      = EXCLUDED.short_name,
  genus           = EXCLUDED.genus,
  updated_at      = now();
